{
  "diagnostic_hints": [
    "学生常误以为 range 的右端点包含在结果中，请提醒检查切片边界。",
    "对于列表索引，建议先用 0 到 N-1 的小数字进行手算验证。",
    "如果字符串操作失败，请检查是否混淆了字符串和列表的索引规则。"
  ],
  "practice_problems": [
    {
      "id": "py43-001",
      "type": "fill_in_blank",
      "hint": "尝试先写出 range 的起始和结束值，再观察输出。",
      "sample_io": {
        "input": "start=0, end=5",
        "output": "0 1 2 3 4"
      },
      "expected_output_pattern": "0 1 2 3 4"
    },
    {
      "id": "py43-002",
      "type": "debugging",
      "hint": "检查你的循环条件，是否多执行了一次迭代？",
      "sample_io": {
        "input": "list=[1,2,3], condition=len(x)>1",
        "output": "1 2 3"
      },
      "expected_output_pattern": "1 2"
    },
    {
      "id": "py43-003",
      "type": "short_answer",
      "hint": "思考一下，如果列表长度是 0，你的代码会怎样？",
      "sample_io": {
        "input": "list=[]",
        "output": "空列表"
      },
      "expected_output_pattern": "空列表"
    }
  ]
}
